style.css:
@-moz-document domain("chess.com") {
/* ===== BOARD COLORS ===== */

  /* Light squares */
  .board .square.light {
    background: linear-gradient(
      135deg,
      #f8fbff,
      #e6f0ff
    ) !important;
  }

  /* Dark squares */
  .board .square.dark {
    background: linear-gradient(
      135deg,
      #2b4f9c,
      #1e3a73
    ) !important;
  }

  /* ===== SIX EYES OVERLAY (SUBTLE) ===== */

  .board {
    position: relative !important;
  }

  .board::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 0;

    background-image: url("data:image/svg+xml;utf8,\
<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 500 500'>\
  <defs>\
    <radialGradient id='g' cx='50%' cy='50%' r='50%'>\
      <stop offset='0%' stop-color='%23a6c8ff' stop-opacity='0.35'/>\
      <stop offset='60%' stop-color='%236fa8ff' stop-opacity='0.15'/>\
      <stop offset='100%' stop-color='%23000000' stop-opacity='0'/>\
    </radialGradient>\
  </defs>\
  <ellipse cx='250' cy='250' rx='170' ry='90' fill='url(%23g)'/>\
  <circle cx='250' cy='250' r='38' fill='%238bbcff' fill-opacity='0.25'/>\
  <circle cx='250' cy='250' r='16' fill='%23ffffff' fill-opacity='0.35'/>\
</svg>");

    background-repeat: no-repeat;
    background-position: center;
    background-size: 45%;
    opacity: 0.08;
  }

  /* Ensure pieces & highlights stay above overlay */
  .board .square,
  .piece,
  .highlight,
  .legal-move {
    position: relative;
    z-index: 1;
  }
}
